SELECT formatDateTime(occurred_at, '%G-W%V') AS `isoWeek`, toMonday(occurred_at) AS `isoWeekStart`, COUNT(events.event_id) AS `events`, COUNT(DISTINCT events.user_id) AS `activeUsers`, MIN(events.occurred_at) AS `firstEventAt`, MAX(events.occurred_at) AS `lastEventAt` FROM events WHERE toDateTime64(events.occurred_at, 9, 'UTC') BETWEEN ? AND ? GROUP BY `isoWeek`, `isoWeekStart` ORDER BY `isoWeekStart` ASC
